<?php
namespace Sellio\Connector;
defined( 'ABSPATH' ) || exit;
final class Serializer {
	private static function date( $date ) { return $date ? $date->date( 'c' ) : null; }
	private static function money( $value ) { return null === $value || '' === $value ? null : (string) $value; }
	private static function address( $order, $prefix ) { return array( 'first_name' => $order->{"get_{$prefix}_first_name"}(), 'last_name' => $order->{"get_{$prefix}_last_name"}(), 'company' => $order->{"get_{$prefix}_company"}(), 'address_1' => $order->{"get_{$prefix}_address_1"}(), 'address_2' => $order->{"get_{$prefix}_address_2"}(), 'city' => $order->{"get_{$prefix}_city"}(), 'postcode' => $order->{"get_{$prefix}_postcode"}(), 'country' => $order->{"get_{$prefix}_country"}(), 'state' => $order->{"get_{$prefix}_state"}() ); }
	public static function event( $order, $type, $event_id ) { $s = Settings::all(); return array( 'schema_version' => '1', 'event_id' => $event_id, 'event_type' => $type, 'occurred_at' => gmdate( 'c' ), 'store_id' => $s['store_id'], 'data' => self::order( $order ) ); }
	public static function order( $order ) { $items = array(); foreach ( $order->get_items( 'line_item' ) as $item ) { $product = $item->get_product(); $attrs = array(); if ( $product && $product->is_type( 'variation' ) ) { foreach ( $product->get_attributes() as $k => $v ) { $attrs[ $k ] = $v; } } $items[] = array( 'id' => (string) $item->get_id(), 'product_id' => $item->get_product_id() ? (string) $item->get_product_id() : null, 'variation_id' => $item->get_variation_id() ? (string) $item->get_variation_id() : null, 'sku' => $product && $product->get_sku() ? $product->get_sku() : null, 'name' => $item->get_name(), 'quantity' => (int) $item->get_quantity(), 'subtotal' => self::money( $item->get_subtotal() ), 'subtotal_tax' => self::money( $item->get_subtotal_tax() ), 'total' => self::money( $item->get_total() ), 'total_tax' => self::money( $item->get_total_tax() ), 'variation_attributes' => $attrs ); }
		return array( 'id' => (string) $order->get_id(), 'number' => (string) $order->get_order_number(), 'created_at' => self::date( $order->get_date_created() ), 'modified_at' => self::date( $order->get_date_modified() ), 'status' => $order->get_status(), 'currency' => $order->get_currency(), 'total' => self::money( $order->get_total() ), 'discount_total' => self::money( $order->get_discount_total() ), 'discount_tax' => self::money( $order->get_discount_tax() ), 'shipping_total' => self::money( $order->get_shipping_total() ), 'shipping_tax' => self::money( $order->get_shipping_tax() ), 'cart_tax' => self::money( $order->get_cart_tax() ), 'total_tax' => self::money( $order->get_total_tax() ), 'customer_id' => $order->get_customer_id() ? (string) $order->get_customer_id() : null, 'billing' => self::address( $order, 'billing' ), 'shipping' => self::address( $order, 'shipping' ), 'email' => $order->get_billing_email() ?: null, 'phone' => $order->get_billing_phone() ?: null, 'payment_method' => $order->get_payment_method_title() ?: null, 'date_paid' => self::date( $order->get_date_paid() ), 'shipping_method' => $order->get_shipping_method() ?: null, 'items' => $items ); }
	public static function product( $p ) { $images = array(); foreach ( array_filter( array_merge( array( $p->get_image_id() ), $p->get_gallery_image_ids() ) ) as $id ) { $images[] = array( 'id' => (string) $id, 'url' => wp_get_attachment_url( $id ), 'alt' => get_post_meta( $id, '_wp_attachment_image_alt', true ) ); } $cats = array_map( static function( $t ) { return array( 'id' => (string) $t->term_id, 'name' => $t->name, 'slug' => $t->slug ); }, get_the_terms( $p->get_id(), 'product_cat' ) ?: array() ); $attrs = array(); foreach ( $p->get_attributes() as $a ) { $attrs[] = array( 'name' => $a->get_name(), 'options' => $a->is_taxonomy() ? wc_get_product_terms( $p->get_id(), $a->get_name(), array( 'fields' => 'names' ) ) : $a->get_options(), 'visible' => $a->get_visible(), 'variation' => $a->get_variation() ); } return array( 'id' => (string) $p->get_id(), 'type' => $p->get_type(), 'supported' => in_array( $p->get_type(), array( 'simple', 'variable', 'variation' ), true ), 'status' => $p->get_status(), 'parent_id' => $p->get_parent_id() ? (string) $p->get_parent_id() : null, 'name' => $p->get_name(), 'slug' => $p->get_slug(), 'sku' => $p->get_sku() ?: null, 'url' => $p->get_permalink(), 'description' => $p->get_description(), 'short_description' => $p->get_short_description(), 'regular_price' => self::money( $p->get_regular_price() ), 'sale_price' => self::money( $p->get_sale_price() ), 'price' => self::money( $p->get_price() ), 'currency' => get_woocommerce_currency(), 'manage_stock' => $p->get_manage_stock(), 'stock_quantity' => $p->get_stock_quantity(), 'stock_status' => $p->get_stock_status(), 'backorders' => $p->get_backorders(), 'categories' => $cats, 'attributes' => $attrs, 'images' => $images, 'created_at' => self::date( $p->get_date_created() ), 'modified_at' => self::date( $p->get_date_modified() ) ); }
}
